CREATE OR REPLACE PROCEDURE sp(arg1 NUMBER, arg2 VARCHAR2, arg3 VARCHAR2, arg4 VARCHAR2) AS
BEGIN
  UPDATE "driver"
     SET "Name" = arg2
   WHERE "Age" > arg1;

  UPDATE "school_bus" sb
     SET "Years_Working" = NVL("Years_Working", 0) + 1
   WHERE "Driver_ID" IN (SELECT "Driver_ID" FROM "driver" WHERE "Age" > arg1);

  IF arg3 IS NOT NULL THEN
    UPDATE "school_bus" sb
       SET "If_full_time" = 'T'
     WHERE "Driver_ID" IN (SELECT "Driver_ID" FROM "driver" WHERE "Age" > arg1 AND "Party" = arg3);
  END IF;

  DELETE FROM "driver" WHERE "Party" IS NULL;

  UPDATE "driver"
     SET "Home_city" = arg4
   WHERE 1=1;

  IF arg3 IS NOT NULL THEN
    UPDATE "driver"
       SET "Party" = arg3
     WHERE "Age" > arg1;

    UPDATE "school_bus" sb
       SET "If_full_time" = 'F'
     WHERE "Driver_ID" IN (
       SELECT "Driver_ID" FROM "driver"
        WHERE "Party" = arg3 AND "Age" <= arg1
     );
  END IF;
END sp;

